    +'#ggBanzuke .ggb-col{overflow:visible}'
    +'#ggBanzuke .ggb-body{min-height:0}'
  +'}'
  +'.ggb{position:absolute;inset:0;display:flex;flex-direction:column;'
    +'background:#e9e1d0 url('+PAPER+') center/cover no-repeat;'
