      +'linear-gradient(0deg, rgba(70,50,22,.30), rgba(70,50,22,0) 30%);'
    +'box-shadow:inset 0 -26px 50px rgba(70,50,22,.30),inset 0 0 40px rgba(70,50,22,.16)}'
